    returnType: "void",
    params: "void",
    callsTo: ["CreateTask","GetCoins","LockPlayerFieldControls","ShowCoinsWindow"],
    lineCount: 5,
    bodyC: "u8 taskId;\n    LockPlayerFieldControls();\n    ShowCoinsWindow(GetCoins(), 1, 1);\n    taskId = CreateTask(Task_PrintRouletteEntryMsg, 0);\n    gTasks[taskId].tCoins = GetCoins();",
